import{_ as s,o as e,c as i,a6 as n}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"信息图、教学演示与UI","description":"","frontmatter":{"id":"information","title":"信息图、教学演示与UI","chapter":"08","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["mermaid","excalidraw"],"order":34,"content_kind":"任务入门"},"headers":[],"relativePath":"information-creative/information.md","filePath":"information-creative/information.md"}'),t={name:"information-creative/information.md"};function p(r,a,l,o,d,c){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="信息图、教学演示与ui-先让关系和数据正确" tabindex="-1">信息图、教学演示与UI，先让关系和数据正确 <a class="header-anchor" href="#信息图、教学演示与ui-先让关系和数据正确" aria-label="Permalink to &quot;信息图、教学演示与UI，先让关系和数据正确&quot;">​</a></h1><p>本节把“商品图制作流程”做成四步信息图，得到结构化文案、可编辑图形和导出预览。图像模型适合风格探索和插图，流程关系、准确数字和按钮文字尽量用矢量或真实界面工具完成。</p><h2 id="_1-把四步写成数据" tabindex="-1">1. 把四步写成数据 <a class="header-anchor" href="#_1-把四步写成数据" aria-label="Permalink to &quot;1. 把四步写成数据&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 输入：真实商品照片、事实表、用途</span></span>
<span class="line"><span>2 背景：无字环境、光线与留白</span></span>
<span class="line"><span>3 合成：商品原像素、蒙版、阴影、准确文字</span></span>
<span class="line"><span>4 检查：结构、颜色、数值、裁切、源文件</span></span></code></pre></div><p>每个框只写一个动作，箭头表示实际顺序。想加“通过率90%”先提供真实统计；没有数据就不画效果数字。</p><h2 id="_2-生成排版简报" tabindex="-1">2. 生成排版简报 <a class="header-anchor" href="#_2-生成排版简报" aria-label="Permalink to &quot;2. 生成排版简报&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把以下四步流程整理为一张教学信息图。保持输入、背景、合成、检查的依赖顺序，不增加未提供的统计与结果。</span></span>
<span class="line"><span>输出每个框的短标题、两条以内说明、箭头关系和布局建议。背景浅色，深灰文字，橙色只强调关键动作。图形必须能编辑，准确文字单独保留；若做风格插图，不生成虚假软件界面。另列需要来源核对的数据。</span></span></code></pre></div><h2 id="_3-用mermaid或画图工具完成关系" tabindex="-1">3. 用Mermaid或画图工具完成关系 <a class="header-anchor" href="#_3-用mermaid或画图工具完成关系" aria-label="Permalink to &quot;3. 用Mermaid或画图工具完成关系&quot;">​</a></h2><p>在支持Mermaid的编辑器或绘图工具里把四框连起来，检查有没有跳步和反向箭头。需要交给设计师时给节点文字与关系表；图像工具只做无字装饰或风格探索，不代替逻辑结构。<a href="https://mermaid.js.org/intro/" target="_blank" rel="noreferrer">Mermaid官方文档</a>。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[真实照片与事实表] --&gt; B[无字背景]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt; C[真实主体合成]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[文字与成品检查]</span></span></code></pre></div><p>本网站不把Mermaid代码冒充已生成图形，下载件中保留可复制源代码。UI概念稿也需要单独列导航、按钮行为和错误状态；漂亮屏幕不能证明交互已经实现。</p><p>完整任务词<a href="./../prompts/P04">P04</a>。真实数据图、可点击UI与导出案例尚待补。</p>`,12)])])}const u=s(t,[["render",p]]);export{m as __pageData,u as default};
